# ---------- Config ----------
# The setup script generated by MEDomics writes medfl_agent.json next to this file; environment variables win over it.
def _load_agent_config() -> Dict[str, Any]:
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "medfl_agent.json")
    try:
        with open(path, encoding="utf-8-sig") as f:
            config = json.load(f)
        return config if isinstance(config, dict) else {}
    except FileNotFoundError:
        return {}
    except Exception as e:
        print(f"[agent] Ignoring the invalid config file {path}: {e}", file=sys.stderr)
        return {}


_AGENT_CONFIG = _load_agent_config()


def _setting(env_name: str, config_key: str, default=None):
    return os.getenv(env_name) or _AGENT_CONFIG.get(config_key) or default


