import shutil
import re


def log(msg: str):
    os.makedirs(LOG_DIR, exist_ok=True)
    with open(AGENT_LOG, "a", encoding="utf-8") as f:
        f.write(f"[{time.ctime()}] {msg}\n")
    print(msg, flush=True)


def ensure_dirs():
    for p in (BASE_DIR, LOG_DIR, RUN_DIR, DATA_DIR):
        os.makedirs(p, exist_ok=True)


def pick_venv_creator_python() -> str:
    """
    Pick a Python interpreter capable of creating the MEDfl venv.

    Preference:
      - Windows: py launcher, targeting MEDFL_PY (default 3.12)
      - Linux/macOS: python3.12, python3.11, python3.10
      - Fallback: current interpreter
    """
    if os.name == "nt":
        py_launcher = shutil.which("py")
        if py_launcher:
            return py_launcher

        for cand in ("python3.12", "python3.11", "python3.10", "python"):
            p = shutil.which(cand)
            if p:
                return p

        return sys.executable

    for cand in ("python3.12", "python3.11", "python3.10"):
        p = shutil.which(cand)
        if p:
            return p

    return sys.executable


def _venv_creator_cmd(creator: str) -> List[str]:
    """Build the command used to create VENV_DIR."""
    if os.name == "nt" and os.path.basename(creator).lower() in ("py", "py.exe"):
        requested_python = PY_VERSION
        return [creator, f"-{requested_python}", "-m", "venv", VENV_DIR]

    return [creator, "-m", "venv", VENV_DIR]


def run_pip_install(args: List[str], timeout: int = 600) -> None:
    """
    Run pip inside the MEDfl virtual environment.

    Full stdout/stderr are written to agent.log. Raises RuntimeError if pip
    returns a non-zero exit code.
    """
    if not os.path.exists(VENV_PY):
        raise RuntimeError(f"Virtual environment Python not found: {VENV_PY}")

    cmd = [VENV_PY, "-m", "pip"] + args
    log(f"[pip] Executing: {' '.join(shlex.quote(x) for x in cmd)}")

    res = subprocess.run(
        cmd,
        text=True,
        capture_output=True,
        timeout=timeout,
    )

    if res.stdout:
        log("[pip] stdout:\n" + res.stdout.strip())
    if res.stderr:
        log("[pip] stderr:\n" + res.stderr.strip())

    if res.returncode != 0:
        raise RuntimeError(f"pip failed rc={res.returncode}")


def create_venv() -> None:
    """Create a fresh MEDfl virtual environment."""
    ensure_dirs()

    creator = pick_venv_creator_python()
    cmd = _venv_creator_cmd(creator)

    log(f"[agent] Creating MEDfl venv using: {' '.join(shlex.quote(x) for x in cmd)}")
    subprocess.check_call(cmd, timeout=600)

    if not os.path.exists(VENV_PY):
        raise RuntimeError(f"venv creation completed but Python was not found at {VENV_PY}")


def install_medfl_dependencies() -> None:
    """
    Install the agent dependencies and the required MEDfl version into VENV_DIR.

    MEDfl is allowed to resolve its own scientific dependencies so that we do
    not accidentally force an incompatible NumPy / pandas / scipy / sklearn
    combination.
    """
    run_pip_install(
        ["install", "--upgrade", "pip", "setuptools", "wheel"],
        timeout=600,
    )

    deps = [
        "websockets",
        "psutil",
        "GPUtil",
        f"MEDfl=={REQUIRED_MEDFL_VERSION}",
    ]

    run_pip_install(
        ["install", "--no-cache-dir"] + deps,
        timeout=1200,
    )


def verify_medfl_installed(required_version=REQUIRED_MEDFL_VERSION) -> bool:
    """
    Verify that MEDfl can actually be imported from the dedicated venv and,
    optionally, that the expected package version is installed.

    A full traceback is captured when an import fails. This is important for
    diagnosing binary ABI problems such as NumPy/pandas/scikit-learn mismatch.
    """
    if not os.path.exists(VENV_PY):
        log(f"[verify] MEDfl venv Python does not exist: {VENV_PY}")
        return False

    version_check_code = f"""
import sys
import traceback

try:
    import torch
    import MEDfl
    from MEDfl.rw.client import FlowerClient

    try:
        from importlib.metadata import version
    except ImportError:
        from importlib_metadata import version

    required = {repr(required_version)}

    if required:
        installed = version("MEDfl")
        if installed != required:
            sys.stderr.write(
                f"MEDfl version mismatch: {{installed}} != {{required}}\\n"
            )
            sys.exit(2)

except Exception:
    traceback.print_exc(file=sys.stderr)
    sys.exit(1)
"""

    try:
        result = subprocess.run(
            [VENV_PY, "-c", version_check_code],
            capture_output=True,
            text=True,
            timeout=60,
        )

        if result.stdout.strip():
            log("[verify] stdout:\n" + result.stdout.strip())

        if result.returncode == 0:
            log(f"[verify] MEDfl {required_version} import verified successfully")
            return True

        stderr = result.stderr.strip()

        if result.returncode == 2:
            log(f"[verify] MEDfl version mismatch:\n{stderr}")
        else:
            log(f"[verify] MEDfl import or check failed:\n{stderr}")

        return False

    except Exception as e:
        log(f"[verify] Verification error: {e}")
        return False


def remove_venv() -> None:
    """Remove the MEDfl virtual environment."""
    if not os.path.exists(VENV_DIR):
        return

    log(f"[agent] Removing virtual environment: {VENV_DIR}")

    last_error = None

    # Antivirus/indexers on Windows can briefly hold files open.
    for attempt in range(1, 4):
        try:
            shutil.rmtree(VENV_DIR)
            return
        except Exception as e:
            last_error = e
            log(f"[agent] Failed to remove venv (attempt {attempt}/3): {e}")
            time.sleep(1)

    raise RuntimeError(f"Unable to remove broken venv: {last_error}")


def rebuild_venv() -> bool:
    """
    Completely rebuild the MEDfl virtual environment.

    This is deliberately preferred over an in-place dependency repair when
    verification fails, because compiled Python packages can remain ABI
    incompatible after a normal pip install/upgrade.
    """
    log("[agent] Rebuilding MEDfl virtual environment...")

    try:
        remove_venv()
        create_venv()
        install_medfl_dependencies()

        if verify_medfl_installed():
            log("[agent] MEDfl virtual environment rebuilt successfully")
            return True

        log("[agent] Rebuilt environment failed MEDfl verification")
        return False

    except Exception as e:
        log(f"[agent] Virtual environment rebuild failed: {e}")
        return False


def ensure_medfl_available(repair: bool = True) -> bool:
    """
    Ensure MEDfl exists and imports correctly in VENV_DIR.

    If verification fails, rebuild the whole environment once.
    """
    if verify_medfl_installed():
        return True

    if not repair:
        return False

    log("[agent] MEDfl unavailable or broken; attempting clean environment rebuild...")
    return rebuild_venv()


def ensure_env_and_reexec():
    """
    Ensure the agent itself is running from the dedicated MEDfl virtual env.

    This must not depend on whether a package such as `websockets` happens to
    exist in the system Python installation.
    """
    ensure_dirs()

    expected_python = os.path.normcase(os.path.abspath(VENV_PY))
    current_python = os.path.normcase(os.path.abspath(sys.executable))

    if IN_VENV and current_python == expected_python:
        return

    # If the environment does not exist yet, create and install it.
    if not os.path.exists(VENV_PY):
        log("[agent] MEDfl virtual environment not found")
        create_venv()
        install_medfl_dependencies()

    # If the existing venv is broken, repair it before re-exec.
    if not ensure_medfl_available(repair=True):
        log("[agent] CRITICAL: MEDfl installation failed")
        sys.exit(1)

    log(f"[agent] Re-executing agent with venv Python: {VENV_PY}")

    env = os.environ.copy()
    env["MEDFL_IN_VENV"] = "1"

    script_path = os.path.abspath(__file__)

    if os.name == "nt":
        # os.execve works on Windows, but spawning and exiting is more robust
        # for scripts launched from PowerShell, Task Scheduler, or services.
        result = subprocess.run([VENV_PY, script_path], env=env)
        sys.exit(result.returncode)

    os.execve(VENV_PY, [VENV_PY, script_path], env)


# ---------- Bootstrap ----------
# Always force the agent into its dedicated environment.
if not IN_VENV or os.path.normcase(os.path.abspath(sys.executable)) != os.path.normcase(os.path.abspath(VENV_PY)):
    ensure_env_and_reexec()

