import websockets  # noqa: E402
import psutil      # noqa: E402
 
 
def hello():
    msg = {
        "type": "HELLO",
        "id": AGENT_ID or f"{socket.gethostname()}-{platform.system().lower()}",
    }
    if TOKEN:
        msg["token"] = TOKEN
    return msg
 
 
# ---------- Process detection (no PID files) ----------
 
def _normalize_path(p: str) -> str:
    try:
        return os.path.realpath(p)
    except Exception:
        return p
 
def _cmdline_contains(p: psutil.Process, fragment: str) -> bool:
    try:
        return fragment in " ".join(p.cmdline())
    except Exception:
        return False
 
def list_running_clients(script_path: str) -> List[Tuple[int, str]]:
    """
    Find processes that *exactly* look like our client:
      [VENV_PY, script_path, ...]
    Returns list of (pid, "cmdline as string").
    """
    py = _normalize_path(VENV_PY)
    sp = _normalize_path(script_path)
    out: List[Tuple[int, str]] = []
 
    for p in psutil.process_iter(attrs=["pid", "cmdline", "status"]):
        try:
            # Skip zombies/defunct
            status = p.info.get("status")
            if status in (psutil.STATUS_ZOMBIE, getattr(psutil, "STATUS_DEAD", "dead")):
                continue
 
            cmd: List[str] = p.info.get("cmdline") or []
            if len(cmd) < 2:
                continue
 
            c0 = _normalize_path(cmd[0])
            c1 = _normalize_path(cmd[1])
 
            # macOS launchd keeps cmdline intact; match exactly:
            if c0 == py and c1 == sp:
                out.append((p.info["pid"], " ".join(cmd)))
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
        except Exception as e:
            log(f"[agent] process_iter inspect error: {e}")
            continue
 
    return out
 
 
def kill_pid(pid: int, timeout: float = 10.0) -> bool:
    try:
        if not psutil.pid_exists(pid):
            return True
        p = psutil.Process(pid)
        p.terminate()
        try:
            p.wait(timeout=timeout)
            return True
        except psutil.TimeoutExpired:
            p.kill()
            p.wait(timeout=5.0)
            return True
    except Exception as e:
        log(f"[agent] kill_pid({pid}) error: {e}")
    return False
 
 
# ---------- Core logic ----------
 
def compute_csv_stats(path: str, sample_rows: int = 5) -> Dict[str, Any]:
    stats: Dict[str, Any] = {}
    path = os.path.abspath(path)
    stats["path"] = path
    stats["exists"] = os.path.exists(path)
    if not stats["exists"]:
        return stats
 
    try:
        st = os.stat(path)
        stats["file_size_bytes"] = st.st_size
        stats["modified_time"] = time.ctime(st.st_mtime)
    except Exception:
        pass
 
    try:
        import pandas as pd
        df = pd.read_csv(path)
        stats["n_rows"] = int(df.shape[0])
        stats["n_cols"] = int(df.shape[1])
        stats["columns"] = list(map(str, df.columns.tolist()))
        stats["dtypes"] = {c: str(t) for c, t in df.dtypes.items()}
        stats["null_counts"] = {c: int(df[c].isna().sum()) for c in df.columns}
        stats["head"] = df.head(sample_rows).to_dict(orient="records")
        num_cols = df.select_dtypes(include=["number"])
        if not num_cols.empty:
            desc = df.select_dtypes(include=["number"]).describe().to_dict()
            stats["numeric_summary"] = {k: {kk: (float(vv) if hasattr(vv, "__float__") else vv)
                                            for kk, vv in d.items()} for k, d in desc.items()}
        stats["engine"] = "pandas"
        return stats
    except Exception:
        pass
 
    n_rows = 0
    columns = []
    null_counts = defaultdict(int)
    head = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        try:
            columns = next(reader)
        except StopIteration:
            columns = []
        for i, row in enumerate(reader):
            n_rows += 1
            if i < sample_rows:
                head.append(dict(zip(columns, row)))
            for c, v in zip(columns, row):
                if v == "" or v.lower() == "na" or v.lower() == "null":
                    null_counts[c] += 1
    stats["n_rows"] = n_rows
    stats["n_cols"] = len(columns)
    stats["columns"] = columns
    stats["null_counts"] = dict(null_counts)
    stats["head"] = head
    stats["engine"] = "csv"
    return stats
 
 
def resolve_holdout_path(file_name: Any) -> str:
    """
    Path of the holdout file in DATA_DIR. Only a file name is accepted (any folder
    part sent by the server is ignored), so the server cannot read files outside DATA_DIR.
    """
    name = os.path.basename(str(file_name or DEFAULT_HOLDOUT_FILE).replace("\\", "/").strip())
    if not name.lower().endswith(".csv"):
        raise ValueError(f"invalid-holdout-file:{name} (a .csv file name is expected)")
    if name == "dataset.csv":
        raise ValueError("invalid-holdout-file:dataset.csv is the training dataset")
    return os.path.join(DATA_DIR, name)


# --- CHECK_IDS support (helper) -----------------------------------------
def _check_ids_in_csv(path: str, column: str, ids: List[Any]) -> Dict[str, Any]:
    """
    Returns:
      {
        "exists_all": bool,
        "present_ids": [..],
        "missing_ids": [..],
        "checked_count": int,
        "column": str
      }
    """
    result: Dict[str, Any] = {
        "exists_all": False,
        "present_ids": [],
        "missing_ids": [],
        "checked_count": 0,
        "column": column
    }
 
    if not os.path.exists(path):
        raise FileNotFoundError("dataset-not-found")
 
    # Normalize the targets as strings (trimmed)
    targets = [str(x).strip() for x in (ids or [])]
    if len(targets) == 0:
        raise ValueError("no-ids-provided")
 
    # Build a set of values in the given column
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None or column not in reader.fieldnames:
            raise KeyError("column-not-found")
        seen = set()
        for row in reader:
            val = row.get(column)
            if val is not None:
                seen.add(str(val).strip())
 
    present = [x for x in targets if x in seen]
    missing = [x for x in targets if x not in seen]
 
    result["present_ids"] = present
    result["missing_ids"] = missing
    result["checked_count"] = len(targets)
    result["exists_all"] = len(missing) == 0
    return result
# --- END CHECK_IDS support ----------------------------------------------
 
 
def start_medfl(
    server_addr: str,
    data_path: str,
    dp: str,
    force: bool = False,
    model_type: str = "nn",
    holdout_path: str = None,
):
    """
    Launch a MEDfl real-world client.
 
    model_type:
      - "nn": existing neural network client
      - "xgboost": new XGBoost client

    holdout_path: local holdout CSV for the federated holdout test, or None.
    The client only reads it when the server enables the holdout test.
    """
    
    log(f"[agent] start_medfl called with server={server_addr} data={data_path} dp={dp} force={force} model_type={model_type} holdout={holdout_path}")
    if not ensure_medfl_available():
        return -1, "medfl-not-installed"
 
    if os.name == "nt":
        data_path = data_path.replace("\\\\", "\\")
 
    data_path = os.path.abspath(data_path)
    holdout_path = os.path.abspath(holdout_path) if holdout_path else None
 
    model_type = str(model_type or "nn").lower().strip()
 
    if model_type not in ("nn", "xgboost"):
        return -1, f"unsupported-model-type:{model_type}"
 
    os.makedirs(RUN_DIR, exist_ok=True)
 
    script_name = "run_xgboost_client.py" if model_type == "xgboost" else "run_client.py"
    script_path = os.path.join(RUN_DIR, script_name)
 
    if model_type == "xgboost":
        script_content = f"""
import os, sys, traceback
try:
    import torch
    from MEDfl.rw.xgboost.client import XGBoostFlowerClient
 
    client = XGBoostFlowerClient(
        server_address="{server_addr}",
        data_path=r"{data_path}",
        holdout_path={holdout_path!r},
    )
 
    try:
        client.start()
    except Exception as e:
        s = str(e)
        if "StatusCode.UNAVAILABLE" in s or "grpc_status:14" in s or "Connection reset by peer" in s:
            print("Server unavailable / closed connection (treat as normal termination).")
            sys.exit(0)
        raise
 
except SystemExit:
    raise
except Exception as e:
    print(f"XGBoost client startup failed: {{str(e)}}")
    print(traceback.format_exc())
    sys.exit(1)
"""
 
    else:
        if dp == "basic":
            dp_config = "dp=DPConfig(noise_multiplier=0.5,max_grad_norm=1.0,batch_size=64)"
        else:
            dp_config = "dp=None"
 
        script_content = f"""
import os, sys, traceback
try:
    import torch
    from MEDfl.rw.client import FlowerClient, DPConfig
    {dp_config}
 
    client = FlowerClient(
        server_address="{server_addr}",
        data_path=r"{data_path}",
        dp_config=dp,
        holdout_path={holdout_path!r},
    )
 
    try:
        client.start()
    except Exception as e:
        s = str(e)
        if "StatusCode.UNAVAILABLE" in s or "grpc_status:14" in s or "Connection reset by peer" in s:
            print("Server unavailable / closed connection (treat as normal termination).")
            sys.exit(0)
        raise
 
except SystemExit:
    raise
except Exception as e:
    print(f"NN client startup failed: {{str(e)}}")
    print(traceback.format_exc())
    sys.exit(1)
"""
 
    with open(script_path, "w", encoding="utf-8") as f:
        f.write(script_content)
 
    procs = list_running_clients(script_path)
 
    if procs:
        log(f"[agent] Detected running {model_type} client(s): {procs}")
 
        if not force:
            pid = procs[0][0]
            log(
                f"[agent] start_medfl: already-running model_type={model_type} "
                f"pid={pid}, skipping new start"
            )
            return pid, "already-running"
 
        for pid, cmd in procs:
            log(
                f"[agent] start_medfl: force=True, terminating "
                f"model_type={model_type} pid={pid} cmd='{cmd}'"
            )
            kill_pid(pid, timeout=10.0)
 
        time.sleep(0.5)
 
    try:
        cmd = [VENV_PY, script_path]
 
        log(
            f"[agent] Starting MEDfl client "
            f"model_type={model_type} server={server_addr} data={data_path} dp={dp}"
        )
        log(f"[agent] Executing: {' '.join(shlex.quote(arg) for arg in cmd)}")
 
        open(LOG_FILE, "a").close()
        out = open(LOG_FILE, "a")
 
        proc = subprocess.Popen(
            cmd,
            stdout=out,
            stderr=subprocess.STDOUT,
            close_fds=True,
            creationflags=(subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0),
        )
 
        def _watch():
            rc = proc.wait()
            log(f"[agent] {model_type} client process exited rc={rc}")
 
        threading.Thread(target=_watch, daemon=True).start()
 
        return proc.pid, "started"
 
    except Exception as e:
        log(f"[agent] Client startup failed: {str(e)}")
        return -1, f"error: {str(e)}"
    
 
def tail_file(path: str, lines: int = 200, max_bytes: int = 1_000_000):
    """Return last `lines` lines from `path`, reading at most `max_bytes` from the end."""
    st = os.stat(path)
    size = st.st_size
    with open(path, 'rb') as f:
        if size > max_bytes:
            f.seek(-max_bytes, os.SEEK_END)
        data = f.read()
    text = data.decode('utf-8', errors='replace')
    tail = '\n'.join(text.splitlines()[-lines:])
    return tail, size
 
 
async def connect_to_server():
    while True:
        try:
            url = CTRL_URL.replace("http://", "ws://").replace("https://", "wss://")
            async with websockets.connect(url, ping_interval=30, ping_timeout=60) as ws:
                log(f"[agent] Connected to {url}")
                await ws.send(json.dumps(hello()))
                log(f"[agent] HELLO sent id={AGENT_ID or f'{socket.gethostname()}-{platform.system().lower()}'} LOG_FILE={LOG_FILE}")
 
                async for message in ws:
                    try:
                        msg = json.loads(message)
                        mtype = msg.get("type")
 
                        if mtype == "HELLO_REJECTED":
                            # the coordinator closes the connection: retry later instead of at once
                            log(f"[agent] The coordinator refused this agent: {msg.get('error')}. Retrying in 60s...")
                            await asyncio.sleep(60)
                            break

                        elif mtype == "RUN_CLIENT":
                            args = msg.get("args", {}) or {}
                            server = args.get("server_addr", "")
                            dpval = args.get("dp", "none")
                            force = bool(args.get("force", False))
 
                            model_type = (
                                args.get("model_type")
                                or args.get("backend")
                                or args.get("modelType")
                                or "nn"
                            )
 
                            model_type = str(model_type).lower().strip()
 
                            log(
                                f"[agent] RUN_CLIENT received "
                                f"server={server} dp={dpval} force={force} model_type={model_type} "
                                f"holdout_file={args.get('holdout_file')}"
                            )

                            # A missing holdout file is not an error: the client reports it
                            # to the server only if the holdout test is enabled
                            try:
                                holdout_path = resolve_holdout_path(args.get("holdout_file"))
                                if not os.path.exists(holdout_path):
                                    log(f"[agent] No holdout file at {holdout_path}")
                                    holdout_path = None
                            except ValueError as e:
                                log(f"[agent] Holdout file ignored: {e}")
                                holdout_path = None
 
                            pid, status = start_medfl(
                                server,
                                os.path.join(DATA_DIR, "dataset.csv"),
                                dpval,
                                force=force,
                                model_type=model_type,
                                holdout_path=holdout_path,
                            )
                            log(f"[agent] RUN_CLIENT result status={status} pid={pid}")
                            await ws.send(json.dumps({"type": "CLIENT_STATUS", "pid": pid, "status": status}))
 
                        elif mtype == "GET_STATS":
                            rid = msg.get("rid")
                            args = msg.get("args", {}) or {}
                            data_path = os.path.join(DATA_DIR, 'dataset.csv')
                            try:
                                st = compute_csv_stats(data_path)
                                # holdout file stats, only when asked
                                if args.get("holdout_file"):
                                    try:
                                        st["holdout"] = compute_csv_stats(resolve_holdout_path(args.get("holdout_file")))
                                    except Exception as e:
                                        st["holdout"] = {"exists": False, "error": str(e)}
                                resp = {"type": "STATS_RESULT", "rid": rid, "ok": True, "args": st}
                            except Exception as e:
                                resp = {"type": "STATS_RESULT", "rid": rid, "ok": False, "args": {"error": str(e)}}
                            await ws.send(json.dumps(resp))
 
                        elif mtype == "GET_LOG":
                            rid = msg.get("rid")
                            args = msg.get("args", {}) or {}
                            lines = int(args.get("lines", 200))
                            log_path = args.get("log_path") or LOG_FILE
                            log(f"[agent] GET_LOG received rid={rid} lines={lines} path={log_path}")
                            try:
                                if not os.path.isabs(log_path):
                                    log_path = os.path.abspath(log_path)
                                if os.path.exists(log_path):
                                    try:
                                        stt = os.stat(log_path)
                                        log(f"[agent] log exists size={stt.st_size}B mtime={time.ctime(stt.st_mtime)}")
                                    except Exception as e:
                                        log(f"[agent] stat failed for {log_path}: {e}")
                                    try:
                                        content, sz = tail_file(log_path, lines=lines)
                                        preview = content.splitlines()[-1][:120] if content else ""
                                        resp = {"type": "LOG_RESULT", "rid": rid, "ok": True,
                                                "args": {"lines": lines, "size_bytes": int(sz), "text": content, "path": log_path}}
                                        await ws.send(json.dumps(resp))
                                        log(f"[agent] LOG_RESULT sent rid={rid} ok=True bytes_sent≈{len(content)} preview_last_line='{preview}'")
                                    except Exception as e:
                                        log(f"[agent] tail/read failed: {e}")
                                        resp = {"type": "LOG_RESULT", "rid": rid, "ok": False,
                                                "args": {"error": f"tail/read failed: {e}", "path": log_path}}
                                        await ws.send(json.dumps(resp))
                                        log(f"[agent] LOG_RESULT sent rid={rid} ok=False err=tail/read failed")
                                else:
                                    log(f"[agent] log not found at {log_path}")
                                    resp = {"type": "LOG_RESULT", "rid": rid, "ok": False,
                                            "args": {"error": "log not found", "path": log_path}}
                                    await ws.send(json.dumps(resp))
                                    log(f"[agent] LOG_RESULT sent rid={rid} ok=False err=log not found")
                            except Exception as e:
                                log(f"[agent] GET_LOG handling error: {e}")
                                resp = {"type": "LOG_RESULT", "rid": rid, "ok": False, "args": {"error": str(e)}}
                                await ws.send(json.dumps(resp))
                                log(f"[agent] LOG_RESULT sent rid={rid} ok=False err=exception")
 
                        # --- CHECK_IDS handler ---------------------------------------------------
                        elif mtype == "CHECK_IDS":
                            rid = msg.get("rid")
                            args = msg.get("args", {}) or {}
                            col  = args.get("column")
                            ids  = args.get("ids")
 
                            data_path = os.path.join(DATA_DIR, 'dataset.csv')
                            log(f"[agent] CHECK_IDS received rid={rid} column={col} ids_count={len(ids) if isinstance(ids, list) else 'N/A'}")
 
                            try:
                                if not isinstance(col, str) or not col.strip():
                                    raise ValueError("invalid-column")
                                if not isinstance(ids, list):
                                    raise ValueError("invalid-ids")
 
                                result = _check_ids_in_csv(data_path, col.strip(), ids)
                                resp = {
                                    "type": "CHECK_IDS_RESULT",
                                    "rid": rid,
                                    "ok": True,
                                    "args": result  
                                }
                            except Exception as e:
                                resp = {
                                    "type": "CHECK_IDS_RESULT",
                                    "rid": rid,
                                    "ok": False,
                                    "args": {"error": str(e)}
                                }
                            await ws.send(json.dumps(resp))
                        # --- END CHECK_IDS handler ----------------------------------------------
 
                    except Exception as e:
                        log(f"[agent] Message handling error: {e}")
        except Exception as e:
            log(f"[agent] Connection error: {e}, retrying in 10s...")
            await asyncio.sleep(10)
 
 
if __name__ == "__main__":
    ensure_dirs()
    log("[agent] Starting MEDfl agent")

    # At this stage bootstrap already placed us in the dedicated environment.
    # Verify once more without triggering another rebuild loop.
    if not ensure_medfl_available(repair=False):
        log("[agent] CRITICAL: MEDfl not available inside the active venv. Exiting.")
        sys.exit(1)

    asyncio.run(connect_to_server())